def claims(row):
    proof=row.get('review',{})
    return str(proof.get('approved_candidate_id','')).startswith('book56-') or proof.get('root_record_sha256')==REVIEW_SHA

def validate_row(row):
    proof=row.get('review',{});expected=ROWS.get(proof.get('approved_candidate_id'))
    if expected is None or row!=expected:
        raise ValueError('exact Root-approved book56 value, source, scale, page and conditions required')

def valid_book(book):
    return {k:v for k,v in book.items() if k!='subjects'}==PROFILE['book']
